package cn.dreamingfish.dispatch.server;
import cn.dreamingfish.dispatch.server.config.ServerConfig;import cn.dreamingfish.dispatch.server.wiring.ServerPortsFactory;import cn.dreamingfish.dispatch.server.model.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import com.sun.net.httpserver.*;import java.nio.file.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
class CloudAccountHttpTest {
 @TempDir Path root;
 private ServerConfig config(int port){return ServerConfig.load(null,Map.of("SQY_SERVER_ENABLED","true","SQY_SERVER_MODE","real","SQY_ROLE","player","SQY_TARGET_NAME","wire-check","SQY_API_BASE_URL","http://127.0.0.1:"+port+"/api/v1/","SQY_ALLOW_LOOPBACK_HTTP","true","SQY_ACCOUNTS_ENABLED","true","SQY_LOG_DIR",root.resolve("logs").toString(),"SQY_RETRY_MAX","2"));}
 @Test void failureCategoriesAndOversizeAreExplicitAndWritesNeverRetry()throws Exception {
  var response=new AtomicReference<>("{}");var status=new AtomicInteger(401);var count=new AtomicInteger();var server=HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(),0),0);server.createContext("/api/v1/account/login",e->{count.incrementAndGet();e.getRequestBody().readAllBytes();byte[] b=response.get().getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json");e.getResponseHeaders().set("Location","/must-not-follow");e.sendResponseHeaders(status.get(),b.length);e.getResponseBody().write(b);e.close();});server.start();
  try{for(var entry:Map.of(401,"AUTH_FAILED",403,"FORBIDDEN",500,"SERVER_ERROR",429,"RATE_LIMITED",302,"INVALID_DATA",200,"INVALID_DATA").entrySet()){status.set(entry.getKey());count.set(0);var port=ServerPortsFactory.create(config(server.getAddress().getPort())).panelAccounts();assertEquals(entry.getValue(),assertThrows(RemoteFailure.class,()->port.login(CallContext.create(Duration.ofSeconds(2)),"player","test-only long password")).code());assertEquals(1,count.get());}
   status.set(200);response.set("x".repeat(1024*1024+1));var port=ServerPortsFactory.create(config(server.getAddress().getPort())).panelAccounts();assertEquals("INVALID_DATA",assertThrows(RemoteFailure.class,()->port.login(CallContext.create(Duration.ofSeconds(2)),"player","test-only long password")).code());
  }finally{server.stop(0);}
 }
 @Test void slowBodyCannotOutliveTotalBudget()throws Exception {
  var server=HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(),0),0);var workers=Executors.newSingleThreadExecutor();server.setExecutor(workers);server.createContext("/api/v1/account/login",e->{try{e.getRequestBody().readAllBytes();e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(200,0);for(int i=0;i<30;i++){e.getResponseBody().write(' ');e.getResponseBody().flush();Thread.sleep(100);}}catch(Exception ignored){}finally{e.close();}});server.start();
  try{var port=ServerPortsFactory.create(config(server.getAddress().getPort())).panelAccounts();long start=System.nanoTime();assertEquals("CONNECT_FAILED",assertThrows(RemoteFailure.class,()->port.login(CallContext.create(Duration.ofMillis(250)),"player","test-only long password")).code());assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<1500);}finally{server.stop(0);workers.shutdownNow();}
 }

 @Test void delayedOldLoginCannotReplaceNewLoginOrRestoreAccountAfterLogout()throws Exception {
  var oldArrived=new CountDownLatch(1);var releaseOld=new CountDownLatch(1);var workers=Executors.newCachedThreadPool();var server=HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(),0),0);server.setExecutor(workers);String oldId=UUID.randomUUID().toString(),newId=UUID.randomUUID().toString();
  server.createContext("/api/v1/",e->{try{String request=new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);String route=e.getRequestURI().getPath();boolean old=request.contains("old_user");if(route.endsWith("login")&&old){oldArrived.countDown();releaseOld.await(5,TimeUnit.SECONDS);}String name=old?"old_user":"new_user",id=old?oldId:newId,token=(old?"a":"b").repeat(43);var account=Map.of("id",id,"username",name,"displayName",name,"groupId","default","createdAt",Instant.now().toString(),"lastSeenAt",Instant.now().toString());Object data=route.endsWith("logout")?Map.of("loggedOut",true):route.endsWith("me")?Map.of("account",account):Map.of("account",account,"accessToken",token,"expiresAt",Instant.now().plusSeconds(300).toString());byte[] bytes=new cn.dreamingfish.updater.protocol.JsonCodec().write(data);e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);}catch(Exception ignored){}finally{e.close();}});server.start();
  try{var port=ServerPortsFactory.create(config(server.getAddress().getPort())).panelAccounts();var old=CompletableFuture.supplyAsync(()->port.login(CallContext.create(Duration.ofSeconds(5)),"old_user","test-only long password"),workers);assertTrue(oldArrived.await(2,TimeUnit.SECONDS));assertEquals("new_user",port.login(CallContext.create(Duration.ofSeconds(2)),"new_user","test-only long password").username());port.logout(CallContext.create(Duration.ofSeconds(2)));releaseOld.countDown();var failed=assertThrows(ExecutionException.class,()->old.get(3,TimeUnit.SECONDS));assertInstanceOf(RemoteFailure.class,failed.getCause());assertEquals("CANCELLED",((RemoteFailure)failed.getCause()).code());assertEquals("AUTH_FAILED",assertThrows(RemoteFailure.class,()->port.current(CallContext.create(Duration.ofSeconds(2)))).code());}
  finally{releaseOld.countDown();server.stop(0);workers.shutdownNow();}
 }
}
